package org.xingmu.tv;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.provider.Settings;import android.widget.*;import java.util.concurrent.*;
public final class SettingsActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout content=TvUi.root(this);ScrollView scroll=new ScrollView(this);LinearLayout root=TvUi.col(this);scroll.addView(root);content.addView(scroll);root.addView(TvUi.text(this,"设置与内容来源",28,TvUi.INK));TvUi.gap(this,root,16);
 Switch boot=new Switch(this);boot.setText("开机进入星幕 TV");boot.setTextColor(TvUi.INK);boot.setTextSize(19);boot.setChecked(getSharedPreferences("settings",0).getBoolean("boot",false));boot.setOnCheckedChangeListener((v,checked)->{getSharedPreferences("settings",0).edit().putBoolean("boot",checked).apply();if(checked&&Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},6);});root.addView(boot);root.addView(TvUi.text(this,"Android 10+ 通常限制后台直接打开界面。请在小米电视设置中允许自启动；不支持时提供开机提醒。默认桌面是另一种可选方式，不会强制更改。首次安装后须先打开一次应用。",15,TvUi.MUTED));TvUi.gap(this,root,16);
 add(root,"打开系统应用设置",()->launch(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName()))));
 add(root,"可选：设为默认电视桌面",()->new AlertDialog.Builder(this).setTitle("启用桌面入口").setMessage("将让星幕 TV 出现在系统默认桌面候选中。你仍需在系统设置中自行选择；部分小米系统不允许更换。手机也可打开此项目，但不建议替代完整手机桌面。取消此选项不会更改当前桌面。").setNegativeButton("取消",null).setPositiveButton("打开选择",(d,w)->{getPackageManager().setComponentEnabledSetting(new ComponentName(this,"org.xingmu.tv.TvHome"),PackageManager.COMPONENT_ENABLED_STATE_ENABLED,PackageManager.DONT_KILL_APP);launch(new Intent(Settings.ACTION_HOME_SETTINGS));}).show());
 add(root,"关闭桌面候选入口",()->{getPackageManager().setComponentEnabledSetting(new ComponentName(this,"org.xingmu.tv.TvHome"),PackageManager.COMPONENT_ENABLED_STATE_DISABLED,PackageManager.DONT_KILL_APP);TvUi.toast(this,"桌面入口已关闭，请确认系统原桌面已恢复");});
 TvUi.gap(this,root,14);root.addView(TvUi.text(this,"免费与授权来源",22,TvUi.INK));root.addView(TvUi.text(this,"内置 Blender 开放电影（Creative Commons 授权）、央视与国际频道官方观看入口。直播官网可能不适配电视 WebView、要求账号或受到地区限制；不会破解会员、跳过 DRM 或接入盗版 VIP 聚合源。",15,TvUi.MUTED));
 add(root,"导入已授权 JSON 目录",()->{Intent open=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");try{startActivityForResult(open,10);}catch(ActivityNotFoundException e){TvUi.toast(this,"系统没有文件选择器，可改用 HTTPS 目录地址导入");}});
 add(root,"从 HTTPS 地址导入授权目录",()->{EditText url=new EditText(this);url.setSingleLine(true);url.setHint("https://…/catalog.json");new AlertDialog.Builder(this).setTitle("导入已授权目录").setMessage("请只使用获授权的直播或影视目录；需要 authorized: true 与每项 license 字段。格式见项目 README。").setView(url).setNegativeButton("取消",null).setPositiveButton("导入",(d,w)->importTask(()->new CatalogRepository(this).fetch(url.getText().toString().trim()))).show();});
 add(root,"清除自定义目录",()->new AlertDialog.Builder(this).setTitle("清除自定义目录？").setMessage("内置官方入口与开放电影会保留。").setNegativeButton("取消",null).setPositiveButton("清除",(d,w)->{new CatalogRepository(this).clear();status.setText("自定义目录已清除");}).show());
 status=TvUi.text(this,"内置播放器支持 HTTPS MP4、HLS、DASH；无需安装 VPN。",15,TvUi.ACCENT);root.addView(status);add(root,"返回首页",()->finish());
 }
 private void add(LinearLayout root,String text,Runnable action){Button b=TvUi.button(this,text);b.setOnClickListener(v->action.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=TvUi.dp(this,10);root.addView(b,p);}
 private void launch(Intent intent){try{startActivity(intent);}catch(ActivityNotFoundException|SecurityException e){TvUi.toast(this,"系统不提供此入口，请从电视设置手动操作");}}
 private interface Import {int run()throws Exception;}
 private void importTask(Import task){status.setText("正在导入…");worker.execute(()->{String message;try{message="已导入 "+task.run()+" 项授权内容";}catch(Exception e){message="导入失败："+e.getMessage();}String result=message;runOnUiThread(()->{if(!isDestroyed())status.setText(result);});});}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==10&&result==RESULT_OK&&data!=null&&data.getData()!=null)importTask(()->new CatalogRepository(this).save(CatalogRepository.read(getContentResolver().openInputStream(data.getData()))));}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
